package me.pieralini.Aula5.Exercicio7;
import java.util.*; public class Main { static Ponto p(Scanner s,int n){System.out.print("P"+n+" x y: ");return new Ponto(s.nextDouble(),s.nextDouble());} public static void main(String[] args){Scanner s=new Scanner(System.in);Ponto a=p(s,1),b=p(s,2),c=p(s,3),d=p(s,4);Trapezio t=new Trapezio(a,b,c,d);Paralelogramo p=new Paralelogramo(a,b,c,d);Retangulo r=new Retangulo(a,b,c,d);Quadrado q=new Quadrado(a,b,c,d);System.out.println("Trapezio: "+t.area());System.out.println("Paralelogramo: "+p.area());System.out.println("Retangulo: "+r.area());System.out.println("Quadrado: "+q.area());} }
